class Solution {
  public int winningPlayerCount(int n, int[][] pick) {
    int[][] count = new int[n][11];
    for (int[] p : pick) count[p[0]][p[1]]++;
    int answer = 0;
    for (int i = 0; i < n; i++) {
      boolean wins = false;
      for (int c = 0; c <= 10; c++)
        if (count[i][c] > i) {
          wins = true;
          break;
        }
      if (wins) answer++;
    }
    return answer;
  }
}
